from dataclasses import dataclass

@dataclass(order=True, frozen=True)
class Version:
    major: int
    minor: int
    patch: int

    @classmethod
    def parse(cls, s: str) -> 'Version':
        parts = [int(p) for p in s.strip().lstrip('v').split('.')]
        return cls(parts[0], parts[1], parts[2])

def match_range(v_str: str, constraint: str) -> bool:
    v = Version.parse(v_str)
    if constraint.startswith('^'):
        base = Version.parse(constraint[1:])
        # Caret: >=base and <next-major
        upper = Version(base.major + 1, 0, 0)
        return v >= base and v < upper
    elif constraint.startswith('~'):
        base = Version.parse(constraint[1:])
        # Tilde: >=base and <next-minor
        upper = Version(base.major, base.minor + 1, 0)
        return v >= base and v < upper
    return v == Version.parse(constraint)

import unittest
from semver import match_range


class TestMatchRange(unittest.TestCase):
    def test_caret_lower_bound(self):
        self.assertTrue(match_range('1.2.3', '^1.2.3'))
        self.assertTrue(match_range('1.9.9', '^1.2.3'))

    def test_caret_upper_bound(self):
        self.assertFalse(match_range('2.0.0', '^1.2.3'))
        self.assertFalse(match_range('2.0.1', '^1.2.3'))

    def test_caret_below(self):
        self.assertFalse(match_range('1.2.2', '^1.2.3'))

    def test_tilde_lower_bound(self):
        self.assertTrue(match_range('1.2.3', '~1.2.3'))
        self.assertTrue(match_range('1.2.9', '~1.2.3'))

    def test_tilde_upper_bound(self):
        self.assertFalse(match_range('1.3.0', '~1.2.3'))
        self.assertFalse(match_range('1.3.1', '~1.2.3'))

    def test_tilde_below(self):
        self.assertFalse(match_range('1.2.2', '~1.2.3'))

    def test_exact(self):
        self.assertTrue(match_range('1.2.3', '1.2.3'))
        self.assertFalse(match_range('1.2.4', '1.2.3'))

    def test_caret_major_boundary(self):
        self.assertTrue(match_range('0.0.0', '^0.0.0'))
        self.assertFalse(match_range('0.0.1', '^0.0.0'))

    def test_tilde_major_boundary(self):
        self.assertTrue(match_range('1.2.3', '~1.2.3'))
        self.assertFalse(match_range('2.0.0', '~1.2.3'))


if __name__ == '__main__':
    unittest.main()

